begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('38000000-0000-4000-8000-000000000001','charts@example.test','{}'),('38000000-0000-4000-8000-000000000002','charts-inactive@example.test','{}');
update public.profiles set is_active = true where id in ('38000000-0000-4000-8000-000000000001','38000000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('38000000-0000-4000-8000-000000000001','STAFF'),('38000000-0000-4000-8000-000000000002','STAFF');

update public.profiles set is_active=false where id='38000000-0000-4000-8000-000000000002';
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"38000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Care','Family',null,null,'EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Care dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
select lives_ok($$select public.save_patient_qol('39000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,now(),'Caregiver','Eating normally','','','','','','Qualitative only')$$,'Create qualitative QOL draft');
select lives_ok($$select public.save_patient_qol('39000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,now(),'Caregiver','Eating normally','','','','','','Qualitative only')$$,'Retry QOL creation preserves one draft');
select is((select count(*) from public.patient_qol_records),1::bigint,'No duplicate QOL draft');
select throws_ok($$select public.save_patient_qol('39000000-0000-4000-8000-000000000001',(select id from fx where k='other'),1,now(),'Caregiver','Eating normally','','','','','','Qualitative only')$$,'23514','Patient does not match chart','Cannot reparent QOL');
select throws_ok($$select public.save_patient_qol('39000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),0,now(),'Caregiver','Changed','','','','','','Qualitative only')$$,'40001',null,'Stale QOL edit rejected');
select throws_ok($$select public.save_patient_qol(gen_random_uuid(),(select id from fx where k='pet'),null,'-infinity','Caregiver','','','','','','','')$$,'23514',null,'Infinite QOL date rejected');
select lives_ok($$select public.sign_patient_qol('39000000-0000-4000-8000-000000000001',1)$$,'Sign observed chart');
select lives_ok($$select public.sign_patient_qol('39000000-0000-4000-8000-000000000001',1)$$,'Signing retry is idempotent');
select throws_ok($$select public.save_patient_qol('39000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),2,now(),'Caregiver','Rewrite','','','','','','')$$,'23514',null,'Signed QOL cannot be rewritten');
select lives_ok($$select public.add_patient_qol_addendum('39000000-0000-4000-8000-000000000002','39000000-0000-4000-8000-000000000001','Correction retains original')$$,'Append signed QOL correction');
select throws_ok($$update public.patient_qol_addenda set content='erase'$$,'42501',null,'Direct addendum rewrite denied');
select is((select signed_by from public.patient_qol_records where id='39000000-0000-4000-8000-000000000001'),auth.uid(),'Signature actor derives from session');
select lives_ok($$select public.record_lesion_observation('39000000-0000-4000-8000-000000000003','39000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),null,now(),'Shoulder mass','dorsal',0.4,0.3,10,8,null,'Initial measurement',null)$$,'Create mapped lesion and first immutable observation');
select lives_ok($$select public.record_lesion_observation('39000000-0000-4000-8000-000000000003','39000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),null,now(),'Shoulder mass','dorsal',0.4,0.3,10,8,null,'Initial measurement',null)$$,'Observation retry uses stable operation');
select is((select count(*) from public.patient_lesion_observations),1::bigint,'Retry does not duplicate observation');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),'39000000-0000-4000-8000-000000000004',(select id from fx where k='other'),1,now(),'Wrong patient','dorsal',0.4,0.3,10,8,null,'',null)$$,'23514',null,'Lesion cannot move to another patient');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),'39000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),0,now(),'Stale label','dorsal',0.4,0.3,10,8,null,'',null)$$,'40001',null,'Stale map update rejected');
select lives_ok($$select public.record_lesion_observation('39000000-0000-4000-8000-000000000005','39000000-0000-4000-8000-000000000004',(select id from fx where k='pet'),1,now(),'Shoulder mass','left',0.45,0.3,12,9,0,'Recheck',null)$$,'Reopen stable lesion and append recheck');
select is((select version from public.patient_lesions where id='39000000-0000-4000-8000-000000000004'),2,'Map revision increments');
select is((select length_mm from public.patient_lesion_observations where id='39000000-0000-4000-8000-000000000003'),10::numeric,'Original measurement retained');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Bad coordinate','dorsal','NaN',0.3,10,null,null,'',null)$$,'23514',null,'NaN coordinates rejected');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Bad coordinate','dorsal',1.1,0.3,10,null,null,'',null)$$,'23514',null,'Out of bounds coordinates rejected');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Bad measurement','dorsal',0.1,0.3,'NaN',null,null,'',null)$$,'23514',null,'NaN measurements rejected');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Bad measurement','dorsal',0.1,0.3,-1,null,null,'',null)$$,'23514',null,'Negative measurements rejected');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,'-infinity','Bad time','dorsal',0.1,0.3,1,null,null,'',null)$$,'23514',null,'Infinite observation date rejected');
select lives_ok($$select public.prepare_patient_document('39000000-0000-4000-8000-000000000006',(select id from fx where k='other'),null,'other.png','image/png',100,'medical_record','Photo',null,'internal')$$,'Prepare other patient photo');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":100,"mimetype":"image/png"}'::jsonb from public.patient_documents where id='39000000-0000-4000-8000-000000000006';
select public.finalize_patient_document('39000000-0000-4000-8000-000000000006');
select throws_ok($$select public.record_lesion_observation(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Wrong photo','dorsal',0.1,0.3,1,null,null,'','39000000-0000-4000-8000-000000000006')$$,'23514',null,'Cross-patient photo linkage denied');
select lives_ok($$select public.correct_lesion_observation('39000000-0000-4000-8000-000000000007','39000000-0000-4000-8000-000000000003','Initial measurement entered incorrectly')$$,'Reasoned correction append-only');
select is((select count(*) from public.patient_lesion_observations),2::bigint,'Correction retains original observations');
select throws_ok($$delete from public.patient_lesion_observations$$,'42501',null,'Staff cannot erase measurement history');
select set_config('request.jwt.claims','{"sub":"38000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.patient_qol_records),0::bigint,'Inactive staff cannot read QOL');
select throws_ok($$select public.sign_patient_qol('39000000-0000-4000-8000-000000000001',2)$$,'42501','Active staff access required','Inactive staff cannot sign');
set local role anon;
select throws_ok($$select * from public.patient_lesions$$,'42501',null,'Anonymous lesion reads denied');
reset role;
select ok(exists(select 1 from public.audit_logs where table_name='patient_lesion_observations' and user_id='38000000-0000-4000-8000-000000000001'),'Clinical observations audited');
select * from finish();
rollback;
